import { useCallback, useEffect, useState, useTransition } from 'react';
import { type CaipChainId } from '@metamask/utils';
import { useSelector } from 'react-redux';
import { useAnalytics } from '../../../../hooks/useAnalytics';
import {
  MetaMetricsEventCategory,
  MetaMetricsEventName,
} from '../../../../../shared/constants/metametrics';
import {
  convertCaipToHexChainId,
  getRpcDataByChainId,
} from '../../../../../shared/lib/network.utils';
import {
  detectNfts,
  setActiveNetwork,
  setEnabledNetworks,
  setNextNonce,
  updateCustomNonce,
} from '../../../../store/actions';
import {
  getAllChainsToPoll,
  getEnabledNetworksByNamespace,
  getMultichainNetworkConfigurationsByChainId,
  getSelectedMultichainNetworkChainId,
} from '../../../../selectors';
import {
  BUILT_IN_NETWORKS,
  FEATURED_RPCS,
} from '../../../../../shared/constants/network';
import { MultichainNetworks } from '../../../../../shared/constants/multichain/networks';
import { useDispatch } from '../../../../store/hooks';

// TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
// eslint-disable-next-line @typescript-eslint/naming-convention
export enum ACTION_MODE {
  // Displays the search box and network list
  LIST,
  // Displays the form to add or edit a network
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  ADD_EDIT,
  // Displays the page for adding an additional RPC URL
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  ADD_RPC,
  // Displays the page for adding an additional explorer URL
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  ADD_EXPLORER_URL,
  // Displays the page for selecting an RPC URL
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  SELECT_RPC,
  // Add account for non EVM networks
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  ADD_NON_EVM_ACCOUNT,
}

export const useNetworkChangeHandlers = () => {
  const dispatch = useDispatch();
  const { trackEvent, createEventBuilder } = useAnalytics();
  const [isTransitionPending, startTransition] = useTransition();
  const [isNetworkChangePending, setIsNetworkChangePending] = useState(false);
  const isPending = isTransitionPending || isNetworkChangePending;

  const [multichainNetworks] = useSelector(
    getMultichainNetworkConfigurationsByChainId,
  );
  const currentChainId = useSelector(getSelectedMultichainNetworkChainId);

  const enabledNetworksByNamespace = useSelector(getEnabledNetworksByNamespace);
  const allChainIds = useSelector(getAllChainsToPoll);
  const [, evmNetworks] = useSelector(
    getMultichainNetworkConfigurationsByChainId,
  );
  // This value needs to be tracked in case the user changes to a Non EVM
  // network and there is no account created for that network. This will
  // allow the user to add an account for that network.
  const [selectedNonEvmNetwork, setSelectedNonEvmNetwork] =
    useState<CaipChainId>();

  const [actionMode, setActionMode] = useState(ACTION_MODE.LIST);

  useEffect(() => {
    // Fire and forget async operations for better performance
    // setTimeout with 0 delay pushes these operations to the next event loop tick,
    // preventing them from blocking the current execution stack and improving UI responsiveness.
    // This technique is called "yielding to the event loop" - it allows higher priority
    // tasks (like UI updates) to execute first before these background operations run.
    setTimeout(() => {
      dispatch(updateCustomNonce(''));
      dispatch(setNextNonce(''));
      dispatch(detectNfts(allChainIds));
    }, 0);
  }, [enabledNetworksByNamespace, dispatch, allChainIds]);

  const handleEvmNetworkChange = useCallback(
    async (chainId: CaipChainId) => {
      const hexChainId = convertCaipToHexChainId(chainId);

      const { defaultRpcEndpoint } = getRpcDataByChainId(chainId, evmNetworks);
      const finalNetworkClientId = defaultRpcEndpoint.networkClientId;

      setIsNetworkChangePending(true);
      try {
        // Defer expensive Home/Routes re-renders so the network list stays responsive.
        // Promise.resolve unwraps thunk promises so isPending covers the background switch.
        await new Promise<void>((resolve, reject) => {
          startTransition(() => {
            Promise.all([
              Promise.resolve(dispatch(setEnabledNetworks(hexChainId))),
              Promise.resolve(dispatch(setActiveNetwork(finalNetworkClientId))),
            ]).then(() => resolve(), reject);
          });
        });
      } finally {
        setIsNetworkChangePending(false);
      }
    },
    [dispatch, evmNetworks, startTransition],
  );

  const handleNonEvmNetworkChange = useCallback(
    async (chainId: CaipChainId) => {
      setIsNetworkChangePending(true);
      try {
        await new Promise<void>((resolve, reject) => {
          startTransition(() => {
            Promise.all([
              Promise.resolve(dispatch(setActiveNetwork(chainId))),
              Promise.resolve(dispatch(setEnabledNetworks(chainId))),
            ]).then(() => resolve(), reject);
          });
        });
      } finally {
        setIsNetworkChangePending(false);
      }
    },
    [dispatch, startTransition],
  );

  const getMultichainNetworkConfigurationOrThrow = useCallback(
    (chainId: CaipChainId) => {
      const network = multichainNetworks[chainId];
      if (!network) {
        throw new Error(
          `Network configuration not found for chainId: ${chainId}`,
        );
      }
      return network;
    },
    [multichainNetworks],
  );

  const handleNetworkChange = useCallback(
    async (chainId: CaipChainId) => {
      if (isPending) {
        return;
      }

      const currentChain =
        getMultichainNetworkConfigurationOrThrow(currentChainId);
      const chain = getMultichainNetworkConfigurationOrThrow(chainId);

      if (chain.isEvm) {
        await handleEvmNetworkChange(chainId);
      } else {
        await handleNonEvmNetworkChange(chainId);
      }

      const chainIdToTrack = chain.isEvm
        ? convertCaipToHexChainId(chainId)
        : chainId;
      const currentChainIdToTrack = currentChain.isEvm
        ? convertCaipToHexChainId(currentChainId)
        : currentChainId;

      // Check if the destination network is custom (not built-in, featured, or multichain)
      const hexChainId = chain.isEvm
        ? convertCaipToHexChainId(chain.chainId)
        : chain.chainId;

      const isBuiltInNetwork = Object.values(BUILT_IN_NETWORKS).some(
        (builtInNetwork) => builtInNetwork.chainId === hexChainId,
      );
      const isFeaturedRpc = FEATURED_RPCS.some(
        (featuredRpc) => featuredRpc.chainId === hexChainId,
      );
      const isMultichainProviderConfig = Object.values(MultichainNetworks).some(
        (multichainNetwork) =>
          multichainNetwork === chain.chainId ||
          (chain.isEvm
            ? convertCaipToHexChainId(chain.chainId)
            : chain.chainId) === multichainNetwork,
      );

      const isCustomNetwork =
        !isBuiltInNetwork && !isFeaturedRpc && !isMultichainProviderConfig;

      trackEvent(
        createEventBuilder(MetaMetricsEventName.NavNetworkSwitched)
          .addCategory(MetaMetricsEventCategory.Network)
          .addProperties({
            location: 'Network Menu',
            // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
            // eslint-disable-next-line @typescript-eslint/naming-convention
            chain_id: currentChainIdToTrack,
            // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
            // eslint-disable-next-line @typescript-eslint/naming-convention
            from_network: currentChainIdToTrack,
            // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
            // eslint-disable-next-line @typescript-eslint/naming-convention
            to_network: chainIdToTrack,
            // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
            // eslint-disable-next-line @typescript-eslint/naming-convention
            custom_network: isCustomNetwork,
          })
          .build(),
      );
    },
    [
      getMultichainNetworkConfigurationOrThrow,
      currentChainId,
      handleEvmNetworkChange,
      handleNonEvmNetworkChange,
      trackEvent,
      createEventBuilder,
      isPending,
    ],
  );

  return {
    handleNetworkChange,
    handleEvmNetworkChange,
    handleNonEvmNetworkChange,
    getMultichainNetworkConfigurationOrThrow,
    selectedNonEvmNetwork,
    setSelectedNonEvmNetwork,
    actionMode,
    setActionMode,
    ACTION_MODE,
    isPending,
    startTransition,
  };
};
